import sys
from itertools import product

N, M, K = map(int, sys.stdin.read().split())

def is_prime(x):
    return x >= 2 and all(x % p for p in range(2, x))

allowed = []
for pos in range(1, N + 1):
    ds = [d for d in range(10) if is_prime(d) == is_prime(pos)]
    if pos == 1:
        ds = [d for d in ds if d != 0]
    allowed.append(ds)
count = 0
for digs in product(*allowed):
    v = int(''.join(map(str, digs)))
    if v % M == K:
        count += 1
print(count % (10**9 + 7))

